      deviceAddress: '设备地址',
      clientId: 'Client ID / 客户端',
      host: '主机地址',
      port: '端口',
      database: '数据库名',
      username: '用户名',
      password: '密码',
      workflowName: '流程名称',
      customerGroup: '客户分组',
      method: '请求方法',
      authType: '认证方式',
      token: '访问令牌',
      eventName: '事件名称',
      secret: '密钥 / Secret',
      broker: 'Broker 地址',
      topic: 'Topic',
      nodeId: '节点 ID',
      filePath: '文件路径 / CSV 路径',
      sheetName: '工作表名称',
      delimiter: '分隔符',
